def cached(cache, key=hashkey, lock=None):
    @wraps(cache)
    def decorated_function(*args, **kwargs):
        key_args = (key(args),) if key else args
        with lock:
            try:
                return cache[key_args]
            except KeyError:
                pass
        value = cache[key_args] = cache.get(key_args)
        return value
    return decorated_function

