class LRUCache(dict):
    def __init__(self, maxsize):
        self.maxsize = maxsize
        self.hits = 0
        self.misses = 0

    def get(self, key, default=None):
        try:
            value = super().__getitem__(key)
            self.hits += 1
            return value
        except KeyError:
            self.misses += 1
            return default

    def __setitem__(self, key, value):
        super().__setitem__(key, value)
        self.hits += 1

    def __delitem__(self, key):
        super().__delitem__(key)
        self.misses += 1

def lfu_cache(maxsize=128, typed=False):
    cache = {}
    recent_keys = []
    access_count = {}

    def decorator(func):
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items()))
            if key not in cache:
                cache[key] = func(*args, **kwargs)
                access_count[key] = 1
                recent_keys.append(key)
            else:
                access_count[key] += 1
                recent_keys.remove(key)
                recent_keys.append(key)

            if len(cache) > maxsize:
                # remove least frequently used key
                least_frequent_key = recent_keys[0]
                del cache[least_frequent_key]
                del access_count[least_frequent_key]

            return cache[key]

        return wrapper

    return decorator

