def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """
    Updates a partial last_applied_manifest list from a partial Kubernetes response.

    :param last_applied_manifest: Partial last_applied_manifest being updated.
    :type last_applied_manifest: list
    :param observer_schema: Partial observer_schema.
    :type observer_schema: list
    :param response: Partial response from the Kubernetes API.
    :type response: list
    """
    for field in observer_schema:
        field_name = field.get("field_name")
        if field_name not in response:
            continue
        field_value = response.get(field_name)
        if field_value is None:
            continue
        if "field_type" in field and field.get("field_type") == "object":
            if field_name not in last_applied_manifest:
                last_applied_manifest[field_name] = {}
            update_last_applied_manifest_list_from_resp(last_applied_manifest[field_name], field.get("fields"), field_value)
        else:
            last_applied_manifest[field_name] = field_value
    return last_applied_manifest

