def format(self, sql, params):
    out_params = {}
    if self.in_style == 'named':
        if not isinstance(params, Mapping):
            raise ValueError('Invalid value for params')
        for name, value in params.items():
            out_params['@' + name] = value
    elif self.in_style == 'ordinal':
        if not isinstance(params, Sequence):
            raise ValueError('Invalid value for params')
        for i, value in enumerate(params):
            out_params['@' + str(i)] = value
    else:
        raise ValueError('Invalid in_style value: ' + self.in_style)
    return sql.format(**out_params), out_params

def formatmany(sql, many_params):
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters
    """
    # Check if the input is valid
    if not isinstance(many_params, collections.abc.Iterable):
        raise TypeError("many_params must be an iterable")
    for params in many_params:
        if not isinstance(params, (collections.abc.Mapping, collections.abc.Sequence)):
            raise TypeError("elements of many_params must be a Mapping or Sequence")
    # Replace the in-style parameters with out-style parameters
    formatted_params = []
    for params in many_params:
        if isinstance(params, collections.abc.Mapping):
            formatted_params.append({k: _parameter_str(v) for k, v in params.items()})
        else:
            formatted_params.append([_parameter_str(v) for v in params])
    formatted_sql = sql
    for params in formatted_params:
        formatted_sql = formatted_sql.replace("(", "(" + ", ".join(params) + ") ")
    return formatted_sql, formatted_params

