def parse_frequency(frequency):
    if frequency is None:
        return None

    # Check if the frequency is "always"
    if frequency.lower() == "always":
        return None

    # Try to extract the number and unit of time from the frequency string
    match = re.search(r"^(\d+)\s*(\S+)$", frequency)
    if match:
        num = int(match.group(1))
        unit = match.group(2).lower()

        # Map the unit of time to a corresponding datetime.timedelta attribute
        if unit == "minutes":
            return datetime.timedelta(minutes=num)
        elif unit == "hours":
            return datetime.timedelta(hours=num)
        elif unit == "days":
            return datetime.timedelta(days=num)
        elif unit == "weeks":
            return datetime.timedelta(weeks=num)
        elif unit == "months":
            return datetime.timedelta(days=num * 30)
        elif unit == "years":
            return datetime.timedelta(days=num * 365)
    else:
        raise ValueError(f"Unable to parse frequency: {frequency}")

