def get_parser_option_specs(self, command_name):
    try:
        tree = ET.parse('{}_options.xml'.format(command_name))
        root = tree.getroot()
        options = []
        for option in root.findall('./option'):
            options.append((option.attrib['long'], option.attrib['short'], option.attrib['type']))
        return options
    except FileNotFoundError as e:
        print('Could not find the options xml file for the specified command: {}'.format(command_name))
        raise e
    except ET.ParseError as e:
        print('Failed to parse the options xml file for the specified command: {}'.format(command_name))
        raise e
    except Exception as e:
        print('An unexpected error occurred while retrieving the parser option specs: {}'.format(command_name))
