def validate_min_max_args(self, args):
    # Check if args is iterable
    if not hasattr(args, "__iter__"):
        raise ValueError("args must be an iterable")

    # Check if all elements in args are numbers
    for arg in args:
        if not isinstance(arg, (int, float)):
            raise ValueError("All elements in args must be numbers")

    # Check if any element in args is out of range
    for arg in args:
        if arg < self.min_value or arg > self.max_value:
            raise ValueError("Value out of range")

    return True

